def group_by_color(grid):
    # Count color distribution
    counts = {c: sum(row.count(c) for row in grid) for c in range(10)}
    print("Color counts:", counts)

    # Create new grid with grouped colors
    result = [[0]*len(grid[0]) for _ in range(len(grid))]

    # Put all 6s in left side, 5s in right side
    six_pos = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 6]
    five_pos = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 5]

    # Sort positions - fill top-left to bottom-right
    six_pos.sort()
    five_pos.sort()

    i = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if i < len(six_pos) and (six_pos[i][0] == r and c >= six_pos[i][1]):
                continue
            elif i < len(five_pos) and (five_pos[i][0] == r and c >= five_pos[i][1]):
                continue
            pass

    # Actually let me just pack all 6s to the left, maintaining relative order
    cols_6 = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 6:
                cols_6.add(c)

    cols_5 = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                cols_5.add(c)

    print("6 columns:", cols_6)
    print("5 columns:", cols_5)

    # Simple packing: each row gets its non-zeros packed to start
    for r in range(len(grid)):
        row_nonzero = [v for v in grid[r] if v != 0]
        result[r] = row_nonzero + [0]*(len(grid[0]) - len(row_nonzero))

    return result

packed = group_by_color(input_grid)
print("\nPacked rows:")
for row in packed: print(row)

